export interface ModelPrediction {
  fold: number;
  trueLabel: 'PRE_FLIGHT' | 'POST_FLIGHT';
  predLabel: 'PRE_FLIGHT' | 'POST_FLIGHT';
  probPreFlight: number;
  probPostFlight: number;
}

export interface NasaBiomarkerRecord {
  sampleName: string;
  subjectId: 'C001' | 'C002' | 'C003' | 'C004';
  timepoint: string;
  flightPhase: 'PRE_FLIGHT' | 'POST_FLIGHT';
  study: string;
  cbc: Record<string, number>;
  cmp: Record<string, number>;
  cardio: Record<string, number>;
  immune: Record<string, number>;
  urine: Record<string, number>;
  allFeaturesCount: number;
  rawFeatures: Record<string, number>;
  predictions: Record<'LogisticRegression' | 'RandomForest' | 'MajorityBaseline', ModelPrediction>;
}

export interface FeatureImportanceItem {
  feature: string;
  importance: number;
}

export interface NasaOsdrSourceLink {
  id: string;
  title: string;
  description: string;
  url: string;
}

